import { useEffect, useMemo, useState } from "react";
import PageHeader from "../../components/shared/PageHeader";
import Badge from "../../components/shared/Badge";
import { useToast } from "../../context/ToastContext";
import { useAuth } from "../../context/AuthContext";
import { donorKycApi } from "../../services/api";

const API_BASE = process.env.REACT_APP_API_URL || "http://localhost:5000";

const fileToDataUrl = (file) => new Promise((resolve, reject) => {
  const reader = new FileReader();
  reader.onload = () => resolve({
    name: file.name,
    mimeType: file.type,
    dataUrl: String(reader.result || ""),
  });
  reader.onerror = () => reject(reader.error || new Error("Failed to read file"));
  reader.readAsDataURL(file);
});

const readFiles = async (files) => Promise.all(Array.from(files || []).map(fileToDataUrl));

const statusType = (status) => {
  const normalized = String(status || "NOT_SUBMITTED").toUpperCase();
  if (normalized === "APPROVED") return "green";
  if (normalized === "REJECTED") return "red";
  return "yellow";
};

const normalizeRecord = (record) => record || {
  status: "NOT_SUBMITTED",
  documents: { panFront: [], panBack: [], aadhaarFront: [], aadhaarBack: [] },
};

const DocumentStrip = ({ title, items }) => {
  const docs = Array.isArray(items) ? items : [];
  return (
    <div>
      <div style={{ fontSize: 11, color: "var(--text-3)", textTransform: "uppercase", letterSpacing: 1, marginBottom: 6 }}>{title}</div>
      {docs.length > 0 ? (
        <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
          {docs.map((doc) => (
            <a
              key={doc.imageId || doc.fileUrl}
              href={`${API_BASE}${doc.fileUrl}`}
              target="_blank"
              rel="noreferrer"
              style={{ display: "inline-flex", flexDirection: "column", gap: 6, textDecoration: "none" }}
            >
              <img
                src={`${API_BASE}${doc.fileUrl}`}
                alt={doc.fileName || title}
                style={{ width: 120, height: 88, objectFit: "cover", borderRadius: 12, border: "1px solid var(--border)" }}
              />
              <span style={{ width: 120, fontSize: 11, color: "var(--text-3)", wordBreak: "break-word" }}>{doc.fileName || doc.imageId}</span>
            </a>
          ))}
        </div>
      ) : (
        <div className="text-dim">No files uploaded</div>
      )}
    </div>
  );
};

export default function DonorApprovalsPage() {
  const toast = useToast();
  const { user } = useAuth();
  const donorId = String(user?.donorId || user?.userCert || "").trim();
  const donorCertificate = String(user?.donorCertificate || user?.userCert || donorId || "").trim();
  const [loading, setLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [record, setRecord] = useState(null);
  const [form, setForm] = useState({
    panNumber: "",
    aadhaarNumber: "",
  });
  const [files, setFiles] = useState({
    panFront: [],
    panBack: [],
    aadhaarFront: [],
    aadhaarBack: [],
  });

  const current = useMemo(() => normalizeRecord(record), [record]);

  const loadRecord = async () => {
    if (!donorId) return;
    setLoading(true);
    try {
      const res = await donorKycApi.getByDonor(donorId, { userCert: donorCertificate });
      const data = res?.data || null;
      setRecord(data);
      setForm({
        panNumber: data?.panNumber || "",
        aadhaarNumber: data?.aadhaarNumber || "",
      });
    } catch (error) {
      toast(error?.response?.data?.error || error.message || "Failed to load donor approvals", "error");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadRecord();
  }, [donorId]);

  const onPickFile = (key) => async (event) => {
    try {
      const selected = await readFiles(event.target.files || []);
      setFiles((prev) => ({ ...prev, [key]: selected }));
    } catch (error) {
      toast(error?.message || "Unable to read file", "error");
    }
  };

  const handleSubmit = async () => {
    if (!donorId || !donorCertificate) {
      toast("Donor identity is required", "error");
      return;
    }
    if (!form.panNumber || !form.aadhaarNumber) {
      toast("PAN and Aadhaar numbers are required", "error");
      return;
    }
    if (!files.panFront.length || !files.panBack.length || !files.aadhaarFront.length || !files.aadhaarBack.length) {
      toast("Upload front and back images for both PAN and Aadhaar", "error");
      return;
    }

    setSubmitting(true);
    try {
      const payload = {
        donorId,
        donorCertificate,
        panNumber: form.panNumber,
        aadhaarNumber: form.aadhaarNumber,
        panFrontImages: files.panFront,
        panBackImages: files.panBack,
        aadhaarFrontImages: files.aadhaarFront,
        aadhaarBackImages: files.aadhaarBack,
        createdBy: donorCertificate,
      };
      await donorKycApi.submit(payload);
      toast("KYC documents submitted for NGO review", "success");
      await loadRecord();
    } catch (error) {
      toast(error?.response?.data?.error || error.message || "Failed to submit KYC", "error");
    } finally {
      setSubmitting(false);
    }
  };

  const isApproved = String(current.status || "").toUpperCase() === "APPROVED";
  const isPending = String(current.status || "").toUpperCase() === "PENDING";

  return (
    <div>
      <PageHeader title="Donor Approvals" desc="Submit PAN and Aadhaar documents, then wait for NGO review" />

      <div className="stats-row" style={{ gridTemplateColumns: "repeat(3,1fr)", marginBottom: 16 }}>
        <div className="stat-card gold">
          <div className="stat-label">Donor ID</div>
          <div className="stat-value gold">{donorId || "—"}</div>
        </div>
        <div className="stat-card">
          <div className="stat-label">KYC Status</div>
          <div className="stat-value">{String(current.status || "NOT_SUBMITTED")}</div>
        </div>
        <div className="stat-card">
          <div className="stat-label">Reviewed By</div>
          <div className="stat-value">{current.reviewedBy || "—"}</div>
        </div>
      </div>

      <div className="grid-2">
        <div className="card">
          <div className="card-title" style={{ marginBottom: 14 }}>KYC Submission</div>
          <div className="form-grid section-gap">
            <div className="form-group">
              <label>Donor Certificate</label>
              <input value={donorCertificate} readOnly />
            </div>
            <div className="form-group">
              <label>PAN Number</label>
              <input value={form.panNumber} onChange={(e) => setForm((prev) => ({ ...prev, panNumber: e.target.value }))} placeholder="ABCDE1234F" disabled={isApproved} />
            </div>
            <div className="form-group">
              <label>Aadhaar Number</label>
              <input value={form.aadhaarNumber} onChange={(e) => setForm((prev) => ({ ...prev, aadhaarNumber: e.target.value }))} placeholder="123456789012" disabled={isApproved} />
            </div>
            <div className="form-group">
              <label>PAN Front Image</label>
              <input type="file" accept="image/*" onChange={onPickFile("panFront")} disabled={isApproved} />
            </div>
            <div className="form-group">
              <label>PAN Back Image</label>
              <input type="file" accept="image/*" onChange={onPickFile("panBack")} disabled={isApproved} />
            </div>
            <div className="form-group">
              <label>Aadhaar Front Image</label>
              <input type="file" accept="image/*" onChange={onPickFile("aadhaarFront")} disabled={isApproved} />
            </div>
            <div className="form-group">
              <label>Aadhaar Back Image</label>
              <input type="file" accept="image/*" onChange={onPickFile("aadhaarBack")} disabled={isApproved} />
            </div>
            <div className="form-actions">
              <button className="btn btn-secondary" type="button" onClick={loadRecord} disabled={loading}>
                {loading ? "Refreshing..." : "Refresh Status"}
              </button>
              <button className="btn btn-primary" type="button" onClick={handleSubmit} disabled={submitting || isApproved}>
                {submitting ? "Submitting..." : isApproved ? "Approved" : isPending ? "Update Submission" : "Submit KYC"}
              </button>
            </div>
          </div>
          <div style={{ marginTop: 16, color: "var(--text-3)", fontSize: 12, lineHeight: 1.6 }}>
            Donor top-up and donation actions stay locked until the NGO approves this submission.
          </div>
        </div>

        <div className="card">
          <div className="card-title" style={{ marginBottom: 14 }}>Current Review</div>
          <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap", marginBottom: 16 }}>
            <Badge type={statusType(current.status)}>{String(current.status || "NOT_SUBMITTED")}</Badge>
            <span className="text-dim">Submitted: {current.submittedAt || "—"}</span>
          </div>
          <div style={{ display: "grid", gap: 14 }}>
            <div>
              <div style={{ fontSize: 11, color: "var(--text-3)", textTransform: "uppercase", letterSpacing: 1, marginBottom: 6 }}>Review note</div>
              <div style={{ whiteSpace: "pre-wrap", color: "var(--text-2)" }}>{current.reviewNote || "No review note yet"}</div>
            </div>
            <DocumentStrip title="PAN Front" items={current.documents?.panFront} />
            <DocumentStrip title="PAN Back" items={current.documents?.panBack} />
            <DocumentStrip title="Aadhaar Front" items={current.documents?.aadhaarFront} />
            <DocumentStrip title="Aadhaar Back" items={current.documents?.aadhaarBack} />
          </div>
        </div>
      </div>
    </div>
  );
}
